#' @noRd
#' @param A a tabMatrix.
#' @returns The entries of the diagonal matrix representing the unary cross-product of A.
Ctab_unary_crossprod <- function(A) {
    .Call(`_mcmcsae_Ctab_unary_crossprod`, A)
}

#' Coerce a \code{tabMatrix} to a \code{dgCMatrix}
#'
#' @noRd
#' @param M a \code{tabMatrix} object.
#' @returns The same matrix as a \code{dgCMatrix}.
Ctab2dgC <- function(M) {
    .Call(`_mcmcsae_Ctab2dgC`, M)
}

#' Coerce a \code{tabMatrix} to a \code{matrix}
#'
#' @noRd
#' @param M a \code{tabMatrix} object.
#' @returns The same matrix as an ordinary dense matrix.
Ctab2mat <- function(M) {
    .Call(`_mcmcsae_Ctab2mat`, M)
}

#' Compute sqrt(x) or sqrt(1/x) using Eigen
#'
#' @noRd
#' @param x input vector.
#' @param inv if \code{true} sqrt(1/x) is computed instead of sqrt(x).
#' @returns The computed vector sqrt(x).
sqrtC <- function(x, inv = FALSE) {
    .Call(`_mcmcsae_sqrtC`, x, inv)
}

#' Compute log(x) using Eigen
#'
#' @noRd
#' @param x input vector.
#' @returns The computed vector log(x).
logC <- function(x) {
    .Call(`_mcmcsae_logC`, x)
}

#' Compute exp(x) or exp(-x) using Eigen
#'
#' @noRd
#' @param x input vector.
#' @param neg if false (default) compute exp(x), otherwise exp(-x).
#' @returns The computed vector exp(x) or exp(-x).
expC <- function(x, neg = FALSE) {
    .Call(`_mcmcsae_expC`, x, neg)
}

#' Compute log(1 + exp(x)) in a numerically robust way
#'
#' @noRd
#' @param x input vector.
#' @returns The computed vector log(1 + exp(x)).
#' @references
#'   M. Maechler (2012)
#'     Accurately Computing log(1 - exp(-|a|)) Assessed by the Rmpfr package.
#'     URL: \url{https://cran.r-project.org/package=Rmpfr/vignettes/log1mexp-note.pdf}.
log1pexpC <- function(x) {
    .Call(`_mcmcsae_log1pexpC`, x)
}

#' Compute column-wise log of sum of exponentials for a dense matrix
#'
#' @noRd
#' @param M numeric dense matrix.
#' @returns The vector of column-wise log-sum-exp of M.
logSumExpColwiseC <- function(M) {
    .Call(`_mcmcsae_logSumExpColwiseC`, M)
}

